namespace {
inline uint32_t GetDim(const gert::Shape* s, int i) {
    return static_cast<uint32_t>(s->GetOriginShape().GetDim(i));
}
}

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入q,k,v形状: [B, H, T, HS] (float, ND)
    const gert::Shape* q_shape = context->GetInputShape(0);
    if (q_shape->GetOriginShape().GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }
    uint32_t B  = GetDim(q_shape, 0);
    uint32_t H  = GetDim(q_shape, 1);
    uint32_t T  = GetDim(q_shape, 2);
    uint32_t HS = GetDim(q_shape, 3);

    MinGptCausalAttentionCustomTiling tiling;
    tiling.set_B(B);
    tiling.set_H(H);
    tiling.set_T(T);
    tiling.set_HS(HS);
    tiling.set_BH(B * H);

    // 连续存储: [B, H, T, HS]
    // 每个 (T, HS) 的步长（以元素计）:
    uint32_t strideQ = T * HS;
    tiling.set_strideQ(strideQ);
    tiling.set_strideV(strideQ);
    tiling.set_strideY(strideQ);

    // 每个block处理一个(b,h)，需要一个 T x T 的attention中间矩阵workspace
    uint64_t workspacePerBlockBytes = static_cast<uint64_t>(T) * static_cast<uint64_t>(T) * sizeof(float);
    tiling.set_workspacePerBlockBytes(static_cast<uint32_t>(workspacePerBlockBytes));

    // 设置block数量 = B * H
    context->SetBlockDim(B * H);

    // workspace: 为每个block准备T*T*sizeof(float)大小的缓冲
    size_t* workspaces = context->GetWorkspaceSizes(1);
    workspaces[0] = workspacePerBlockBytes;

    // 保存tiling
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 输出y形状与v同: [B, H, T, HS]
    const gert::Shape* v_shape = context->GetInputShape(2);
    gert::Shape* y_shape = context->GetOutputShape(0);
    *y_shape = *v_shape;
    return GRAPH_SUCCESS;
}

